-- 36: Sponsored posts ("Boost"). A member (or an organisation's manager) pays to show one of their PUBLIC posts to more people,
-- labelled "Sponsored", for a fixed number of days. Modelled on Instagram's boost: choose a post, a goal, an audience and a
-- package; pay; the boost is reviewed against VYBE's ad policy; it runs; the sponsor sees real insights and can stop it.
--
--  * Packages (days + price) are priced here, never by the browser; administrators edit them. Starting prices only.
--  * Payment reuses the existing PayFast / Ozow pipeline as a third order kind (sponsor_orders), exactly like VYBE Verified:
--    priced in Postgres, fulfilled only by the verified payment notification (service role), idempotent per (buyer, key).
--  * State machine, enforced here (no client can make a boost live by editing a field):
--      awaiting_payment -> in_review (payment confirmed) -> live (admin approves) | rejected (admin, with a reason: refund due)
--      live <-> paused (sponsor)          live/paused -> ended (sponsor stops, or the end time passes: no refund)
--      in_review / awaiting_payment -> cancelled (sponsor; a paid, undelivered boost is refund-due in full)
--  * Delivery is a security-definer function that applies the audience, blocks, a daily frequency cap per viewer and each
--    member's "hide this ad"; members cannot read other people's boosts. Counts are one impression (max 3 a day) and one click
--    per member per day, never inflated by the sponsor.
--  * Refunds: a rejected or cancelled-before-delivery boost records what is owed; an administrator refunds through the payment
--    provider and records the reference (admin_mark_sponsor_refunded). Nothing is refunded automatically.
-- Additive. Rollback: drop the functions and tables below and restore the previous notifications_type_check.

create table if not exists public.boost_packages (
  id text primary key check (id ~ '^[a-z0-9_-]{3,20}$'),
  label text not null check (char_length(label) between 3 and 60),
  days integer not null check (days between 1 and 90),
  price_cents integer not null check (price_cents >= 500),
  active boolean not null default true,
  sort integer not null default 100
);
alter table public.boost_packages enable row level security;
drop policy if exists boost_packages_read on public.boost_packages;
create policy boost_packages_read on public.boost_packages for select to authenticated using (active or public.is_admin());
drop policy if exists boost_packages_admin on public.boost_packages;
create policy boost_packages_admin on public.boost_packages for all to authenticated using (public.is_admin()) with check (public.is_admin());
revoke all on public.boost_packages from anon, authenticated;
grant select, insert, update, delete on public.boost_packages to authenticated;
-- Starting prices only: administrators set the real ones in Admin → Sponsored posts.
insert into public.boost_packages (id, label, days, price_cents, sort) values
  ('boost_3', 'Boost · 3 days', 3, 9900, 10), ('boost_7', 'Boost · 7 days', 7, 19900, 20), ('boost_14', 'Boost · 14 days', 14, 34900, 30)
on conflict (id) do nothing;

create table if not exists public.sponsored_posts (
  id uuid primary key default gen_random_uuid(),
  post_id uuid not null references public.posts(id) on delete cascade,
  sponsor uuid not null references public.profiles(id) on delete restrict,
  organization_id uuid references public.organizations(id) on delete set null,
  package_id text not null references public.boost_packages(id),
  days integer not null check (days between 1 and 90),
  total_cents bigint not null check (total_cents >= 500),
  goal text not null default 'engage' check (goal in ('engage', 'profile', 'link', 'plan')),
  cta_label text check (cta_label is null or char_length(cta_label) between 2 and 24),
  cta_url text check (cta_url is null or (char_length(cta_url) between 12 and 500 and cta_url ~ '^https://[^[:space:]]+$')),   -- (a regex repeat count above 255 is invalid in Postgres)
  audience_city text check (audience_city is null or char_length(audience_city) between 2 and 80),
  audience_interests text[] not null default '{}' check (cardinality(audience_interests) <= 10),
  status text not null default 'awaiting_payment' check (status in ('awaiting_payment', 'in_review', 'live', 'paused', 'rejected', 'ended', 'cancelled')),
  review_note text check (review_note is null or char_length(review_note) <= 300),
  reviewed_by uuid references public.profiles(id) on delete set null,
  reviewed_at timestamptz,
  paid_at timestamptz,
  starts_at timestamptz,
  ends_at timestamptz,
  paused_at timestamptz,
  refund_due_cents bigint not null default 0 check (refund_due_cents >= 0),
  refunded_at timestamptz,
  refund_ref text check (refund_ref is null or char_length(refund_ref) <= 120),
  created_at timestamptz not null default now()
);
-- One open boost per post.
create unique index if not exists sponsored_posts_open_key on public.sponsored_posts (post_id) where status in ('awaiting_payment', 'in_review', 'live', 'paused');
create index if not exists sponsored_posts_sponsor_idx on public.sponsored_posts (sponsor, created_at desc);
create index if not exists sponsored_posts_org_idx on public.sponsored_posts (organization_id) where organization_id is not null;
create index if not exists sponsored_posts_package_idx on public.sponsored_posts (package_id);
create index if not exists sponsored_posts_reviewer_idx on public.sponsored_posts (reviewed_by) where reviewed_by is not null;
create index if not exists sponsored_posts_live_idx on public.sponsored_posts (status, ends_at);
create index if not exists sponsored_posts_post_idx on public.sponsored_posts (post_id);

create table if not exists public.sponsor_orders (
