create policy sponsor_stats_read on public.sponsor_stats for select to authenticated
  using (public.is_admin() or exists (select 1 from public.sponsored_posts s where s.id = sponsored_id and (s.sponsor = (select auth.uid()) or public.can_manage_campaigns(s.organization_id))));
