-- ------------------------------------------------------------------------------------------------------ create an order
-- Priced from boost_packages on the server; the browser sends only ids and the sponsor's choices. Idempotent per (buyer, key).
create or replace function public.create_sponsor_order(p_post uuid, p_package text, p_goal text, p_cta_label text, p_cta_url text,
  p_city text, p_interests text[], p_provider text, p_idem text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid(); pk public.boost_packages; po public.posts; sp public.sponsored_posts; o public.sponsor_orders;
  pr public.profiles; recent integer; city text := nullif(btrim(coalesce(p_city, '')), ''); ints text[]; label text := nullif(btrim(coalesce(p_cta_label, '')), '');
  url text := nullif(btrim(coalesce(p_cta_url, '')), '');
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if p_provider not in ('payfast', 'ozow') then raise exception 'Choose PayFast or Ozow'; end if;
  if p_goal not in ('engage', 'profile', 'link', 'plan') then raise exception 'Choose what you want people to do'; end if;
  select * into o from public.sponsor_orders where buyer = me and idempotency_key = p_idem;
  if found then return jsonb_build_object('id', o.id, 'sponsorship_id', o.sponsorship_id, 'status', o.status, 'total_cents', o.total_cents, 'expires_at', o.expires_at); end if;

  select * into po from public.posts where id = p_post;
  if not found then raise exception 'That post is not available'; end if;
  if po.author <> me and not (po.organization_id is not null and public.can_manage_campaigns(po.organization_id)) then raise exception 'You can only boost your own posts'; end if;
  if po.visibility <> 'public' or po.community_id is not null then raise exception 'Only public posts can be boosted'; end if;
  select * into pr from public.profiles where id = me;
  if coalesce(btrim(pr.display_name), '') = '' then raise exception 'Add your name to your profile before boosting'; end if;
  select * into pk from public.boost_packages where id = p_package and active;
  if not found then raise exception 'That package is not available'; end if;

  if p_goal = 'link' then
    if url is null or char_length(url) not between 12 and 500 or url !~ '^https://[^[:space:]]+$' then raise exception 'Enter a secure (https) link'; end if;
    label := coalesce(label, 'Learn more');
  elsif p_goal = 'plan' then
    if po.event_id is null or not exists (select 1 from public.events e where e.id = po.event_id and e.status = 'active') then raise exception 'Link a plan to this post first'; end if;
    url := null; label := coalesce(label, 'View plan');
  elsif p_goal = 'profile' then url := null; label := coalesce(label, 'View profile');
  else url := null; label := null;
  end if;
  if label is not null and char_length(label) not between 2 and 24 then raise exception 'The button text must be 2 to 24 characters'; end if;
  if city is not null and char_length(city) not between 2 and 80 then raise exception 'Enter a valid city'; end if;
  select coalesce(array_agg(x), '{}') into ints from (select distinct left(btrim(i), 30) x from unnest(coalesce(p_interests, '{}')) i where btrim(i) <> '' limit 10) s;

  select count(*) into recent from public.sponsor_orders where buyer = me and created_at > now() - interval '1 hour';
  if recent >= 5 then raise exception 'Too many attempts. Please wait a while.'; end if;
  -- An abandoned checkout must not block the post for ever.
  update public.sponsored_posts s set status = 'cancelled'
   where s.post_id = p_post and s.status = 'awaiting_payment'
     and not exists (select 1 from public.sponsor_orders x where x.sponsorship_id = s.id and x.status = 'pending' and x.expires_at > now());
  if exists (select 1 from public.sponsored_posts where post_id = p_post and status in ('awaiting_payment', 'in_review', 'live', 'paused')) then
    raise exception 'This post already has a boost';
  end if;

  insert into public.sponsored_posts (post_id, sponsor, organization_id, package_id, days, total_cents, goal, cta_label, cta_url, audience_city, audience_interests)
  values (po.id, me, po.organization_id, pk.id, pk.days, pk.price_cents, p_goal, label, url, city, ints) returning * into sp;
  insert into public.sponsor_orders (buyer, sponsorship_id, total_cents, provider, idempotency_key, expires_at)
  values (me, sp.id, pk.price_cents, p_provider, p_idem, now() + interval '30 minutes') returning * into o;
  return jsonb_build_object('id', o.id, 'sponsorship_id', sp.id, 'status', o.status, 'total_cents', o.total_cents, 'expires_at', o.expires_at);
end $$;

-- ------------------------------------------------------------------------------------------ payment webhooks (service role)
create or replace function public.fulfill_sponsor_order(p_order uuid, p_provider text, p_ref text, p_amount_cents bigint) returns void
language plpgsql security definer set search_path = '' as $$
declare o public.sponsor_orders; sp public.sponsored_posts;
begin
  select * into o from public.sponsor_orders where id = p_order for update;
  if not found then raise exception 'Order not found'; end if;
  if o.status = 'paid' then return; end if;
  if o.provider <> p_provider then raise exception 'Provider mismatch'; end if;
  if o.total_cents <> p_amount_cents then raise exception 'Amount mismatch'; end if;
  update public.sponsor_orders set status = 'paid', provider_ref = p_ref, paid_at = now() where id = o.id;
  select * into sp from public.sponsored_posts where id = o.sponsorship_id for update;
  if sp.status = 'awaiting_payment' then
    update public.sponsored_posts set status = 'in_review', paid_at = now() where id = sp.id;
    perform public.notify(o.buyer, 'sponsorship', null, 'post', sp.post_id, 'sp-paid:' || sp.id);
  else
    -- Paid for something we had already cancelled (the checkout expired first): nothing will run, so the money is owed back.
    update public.sponsored_posts set paid_at = now(), refund_due_cents = o.total_cents where id = sp.id;
  end if;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail)
  values (null, 'sponsorship.paid', 'sponsorship', sp.id, jsonb_build_object('order', o.id, 'cents', o.total_cents, 'late', sp.status <> 'awaiting_payment'));
end $$;
create or replace function public.close_sponsor_order(p_order uuid, p_status text) returns void
language plpgsql security definer set search_path = '' as $$
declare sid uuid;
begin
  if p_status not in ('failed', 'cancelled', 'expired') then raise exception 'bad status'; end if;
  update public.sponsor_orders set status = p_status where id = p_order and status = 'pending' returning sponsorship_id into sid;
  if sid is not null then update public.sponsored_posts set status = 'cancelled' where id = sid and status = 'awaiting_payment'; end if;
end $$;

-- ----------------------------------------------------------------------------------------------------------- review (admin)
create or replace function public.admin_review_sponsorship(p_id uuid, p_approve boolean, p_note text) returns void
language plpgsql security definer set search_path = '' as $$
declare sp public.sponsored_posts; note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into sp from public.sponsored_posts where id = p_id for update;
  if not found then raise exception 'Boost not found'; end if;
  if sp.status <> 'in_review' then raise exception 'This boost is not waiting for review'; end if;
  if not p_approve and (note is null or char_length(note) < 3) then raise exception 'Say why it was not approved'; end if;
  if p_approve then
    update public.sponsored_posts set status = 'live', starts_at = now(), ends_at = now() + make_interval(days => sp.days), review_note = note, reviewed_by = auth.uid(), reviewed_at = now() where id = sp.id;
  else
    update public.sponsored_posts set status = 'rejected', review_note = left(note, 300), reviewed_by = auth.uid(), reviewed_at = now(), refund_due_cents = sp.total_cents where id = sp.id;
  end if;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail)
  values (auth.uid(), case when p_approve then 'sponsorship.approved' else 'sponsorship.rejected' end, 'sponsorship', sp.id, jsonb_build_object('note', note));
  perform public.notify(sp.sponsor, 'sponsorship', null, 'post', sp.post_id, 'sp-review:' || sp.id);
end $$;

create or replace function public.admin_mark_sponsor_refunded(p_id uuid, p_ref text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if nullif(btrim(coalesce(p_ref, '')), '') is null then raise exception 'Enter the provider''s refund reference'; end if;
  update public.sponsored_posts set refunded_at = now(), refund_ref = left(btrim(p_ref), 120) where id = p_id and refund_due_cents > 0 and refunded_at is null;
  if not found then raise exception 'Nothing to refund on this boost'; end if;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'sponsorship.refunded', 'sponsorship', p_id, jsonb_build_object('ref', left(btrim(p_ref), 120)));
end $$;

-- ------------------------------------------------------------------------------------------------ sponsor controls
create or replace function public.pause_sponsorship(p_id uuid, p_pause boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare sp public.sponsored_posts;
begin
  select * into sp from public.sponsored_posts where id = p_id for update;
  if not found or not (sp.sponsor = auth.uid() or public.can_manage_campaigns(sp.organization_id)) then raise exception 'Boost not found'; end if;
  if p_pause and sp.status = 'live' then
    update public.sponsored_posts set status = 'paused', paused_at = now() where id = sp.id;
  elsif not p_pause and sp.status = 'paused' then
    -- Time spent paused is given back, so the sponsor still gets the days they paid for.
    update public.sponsored_posts set status = 'live', ends_at = ends_at + (now() - paused_at), paused_at = null where id = sp.id;
  else raise exception 'This boost cannot be %', case when p_pause then 'paused' else 'resumed' end;
  end if;
end $$;

create or replace function public.stop_sponsorship(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare sp public.sponsored_posts;
begin
  select * into sp from public.sponsored_posts where id = p_id for update;
  if not found or not (sp.sponsor = auth.uid() or public.can_manage_campaigns(sp.organization_id)) then raise exception 'Boost not found'; end if;
  if sp.status in ('live', 'paused') then
    update public.sponsored_posts set status = 'ended', ends_at = least(coalesce(ends_at, now()), now()), paused_at = null where id = sp.id;     -- delivered: no refund
  elsif sp.status = 'in_review' then
    update public.sponsored_posts set status = 'cancelled', refund_due_cents = total_cents where id = sp.id;                               -- paid, never shown: refund due
    insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'sponsorship.cancelled_paid', 'sponsorship', sp.id, '{}');
  elsif sp.status = 'awaiting_payment' then
    update public.sponsored_posts set status = 'cancelled' where id = sp.id;
    update public.sponsor_orders set status = 'cancelled' where sponsorship_id = sp.id and status = 'pending';
  else raise exception 'This boost is already finished';
  end if;
end $$;

-- ------------------------------------------------------------------------------------------------------------ delivery
-- Boosts a member may be shown right now. At most p_limit, never their own, never a blocked sponsor's, only for a post that is
-- still public, only inside the audience the sponsor chose, at most 3 times a day each, and never one they hid.
create or replace function public.sponsored_feed(p_placement text default 'home', p_limit integer default 2) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare me uuid := auth.uid(); prof public.profiles; city text; out jsonb;
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if p_placement not in ('home', 'discover') then return '[]'::jsonb; end if;
  select * into prof from public.profiles where id = me;
  city := lower(btrim(split_part(coalesce(prof.location, ''), ',', 1)));
  select coalesce(jsonb_agg(x.j), '[]'::jsonb) into out from (
    select jsonb_build_object('id', s.id, 'post_id', s.post_id, 'goal', s.goal, 'cta_label', s.cta_label, 'cta_url', s.cta_url, 'sponsor', s.sponsor,
             'audience_city', s.audience_city, 'audience_interests', s.audience_interests) j
      from public.sponsored_posts s
      join public.posts p on p.id = s.post_id and p.visibility = 'public' and p.community_id is null
     where s.status = 'live' and s.starts_at <= now() and s.ends_at > now()
       and s.sponsor <> me and not public.is_blocked(me, s.sponsor)
       and (s.audience_city is null or lower(s.audience_city) = city)
       and (cardinality(s.audience_interests) = 0 or exists (select 1 from unnest(s.audience_interests) a join unnest(coalesce(prof.interests, '{}')) b on lower(a) = lower(b)))
       and not exists (select 1 from public.sponsor_hides h where h.user_id = me and h.sponsored_id = s.id)
       and coalesce((select q.n from public.sponsor_seen q where q.user_id = me and q.sponsored_id = s.id and q.day = current_date and q.kind = 'impression'), 0) < 3
     order by coalesce((select q.n from public.sponsor_seen q where q.user_id = me and q.sponsored_id = s.id and q.day = current_date and q.kind = 'impression'), 0), random()
     limit greatest(1, least(coalesce(p_limit, 2), 4))
  ) x;
  return out;
end $$;

-- One impression (up to 3 a day) and one click per member per boost per day. Reach = members who saw it that day.
create or replace function public.track_sponsored(p_id uuid, p_kind text) returns boolean
language plpgsql security definer set search_path = '' as $$
declare me uuid := auth.uid(); first_view boolean := false; cur integer;
begin
  if me is null then raise exception 'Sign in' using errcode = '28000'; end if;
  if p_kind not in ('impression', 'click') then raise exception 'bad kind'; end if;
  if not exists (select 1 from public.sponsored_posts s where s.id = p_id and s.status = 'live' and s.starts_at <= now() and s.ends_at > now() and s.sponsor <> me) then return false; end if;
  if (select coalesce(sum(n), 0) from public.sponsor_seen where user_id = me and day = current_date) >= 600 then return false; end if;
  select n into cur from public.sponsor_seen where user_id = me and sponsored_id = p_id and day = current_date and kind = p_kind;
  if p_kind = 'click' and cur is not null then return false; end if;
  if p_kind = 'impression' and coalesce(cur, 0) >= 3 then return false; end if;
  if cur is null then
    insert into public.sponsor_seen (user_id, sponsored_id, kind, n) values (me, p_id, p_kind, 1) on conflict do nothing;
    first_view := p_kind = 'impression';
  else
    update public.sponsor_seen set n = n + 1 where user_id = me and sponsored_id = p_id and day = current_date and kind = p_kind;
  end if;
  insert into public.sponsor_stats (sponsored_id, day, impressions, clicks, reach)
  values (p_id, current_date, (p_kind = 'impression')::int, (p_kind = 'click')::int, first_view::int)
  on conflict (sponsored_id, day) do update set impressions = public.sponsor_stats.impressions + (p_kind = 'impression')::int,
    clicks = public.sponsor_stats.clicks + (p_kind = 'click')::int, reach = public.sponsor_stats.reach + first_view::int;
  return true;
end $$;

create or replace function public.hide_sponsored(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'Sign in' using errcode = '28000'; end if;
  insert into public.sponsor_hides (user_id, sponsored_id) select auth.uid(), s.id from public.sponsored_posts s where s.id = p_id on conflict do nothing;
end $$;

-- Why am I seeing this? Only what the sponsor chose, in plain terms (never other members' data).
create or replace function public.sponsored_why(p_id uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('city', s.audience_city, 'interests', s.audience_interests, 'sponsor_name',
           coalesce((select o.name from public.organizations o where o.id = s.organization_id), (select p.display_name from public.profiles p where p.id = s.sponsor)))
    from public.sponsored_posts s where s.id = p_id and s.status = 'live' and auth.uid() is not null;
$$;

-- Admin: the review queue and anything refund-due, with the post and sponsor details a reviewer needs.
create or replace function public.admin_sponsorship_queue() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'status', s.status, 'post_id', s.post_id, 'body', p.body, 'media_path', p.media_path, 'media_type', p.media_type,
    'sponsor_name', pr.display_name, 'sponsor_username', pr.username, 'goal', s.goal, 'cta_url', s.cta_url, 'cta_label', s.cta_label, 'audience_city', s.audience_city,
    'audience_interests', s.audience_interests, 'days', s.days, 'total_cents', s.total_cents, 'paid_at', s.paid_at, 'refund_due_cents', s.refund_due_cents,
    'refunded_at', s.refunded_at, 'review_note', s.review_note) order by s.paid_at nulls last)
    from public.sponsored_posts s join public.posts p on p.id = s.post_id join public.profiles pr on pr.id = s.sponsor
   where s.status = 'in_review' or (s.refund_due_cents > 0 and s.refunded_at is null)), '[]'::jsonb);
end $$;

revoke execute on function public.create_sponsor_order(uuid, text, text, text, text, text, text[], text, text), public.fulfill_sponsor_order(uuid, text, text, bigint),
  public.close_sponsor_order(uuid, text), public.admin_review_sponsorship(uuid, boolean, text), public.admin_mark_sponsor_refunded(uuid, text),
  public.pause_sponsorship(uuid, boolean), public.stop_sponsorship(uuid), public.sponsored_feed(text, integer), public.track_sponsored(uuid, text),
  public.hide_sponsored(uuid), public.sponsored_why(uuid), public.admin_sponsorship_queue() from public, anon;
grant execute on function public.create_sponsor_order(uuid, text, text, text, text, text, text[], text, text), public.admin_review_sponsorship(uuid, boolean, text),
  public.admin_mark_sponsor_refunded(uuid, text), public.pause_sponsorship(uuid, boolean), public.stop_sponsorship(uuid), public.sponsored_feed(text, integer),
  public.track_sponsored(uuid, text), public.hide_sponsored(uuid), public.sponsored_why(uuid), public.admin_sponsorship_queue() to authenticated;
revoke execute on function public.fulfill_sponsor_order(uuid, text, text, bigint), public.close_sponsor_order(uuid, text) from authenticated;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.fulfill_sponsor_order(uuid, text, text, bigint), public.close_sponsor_order(uuid, text) to service_role;
  end if;
end $$;

commit;

select item, ok from (values
  ('packages exist', exists (select 1 from public.boost_packages where active)),
  ('boosts and orders cannot be written directly by members', not has_table_privilege('authenticated', 'public.sponsored_posts', 'insert') and not has_table_privilege('authenticated', 'public.sponsored_posts', 'update') and not has_table_privilege('authenticated', 'public.sponsor_orders', 'insert') and not has_table_privilege('authenticated', 'public.sponsor_orders', 'update')),
  ('settling a payment is server-only', not has_function_privilege('authenticated', 'public.fulfill_sponsor_order(uuid,text,text,bigint)', 'execute') and not has_function_privilege('anon', 'public.fulfill_sponsor_order(uuid,text,text,bigint)', 'execute') and not has_function_privilege('authenticated', 'public.close_sponsor_order(uuid,text)', 'execute')),
  ('delivery is for signed-in members; review is admin-checked', has_function_privilege('authenticated', 'public.sponsored_feed(text,integer)', 'execute') and not has_function_privilege('anon', 'public.sponsored_feed(text,integer)', 'execute') and not has_function_privilege('anon', 'public.admin_review_sponsorship(uuid,boolean,text)', 'execute')),
  ('one open boost per post', exists (select 1 from pg_indexes where indexname = 'sponsored_posts_open_key')),
  ('boost notifications are allowed', (select pg_get_constraintdef(oid) from pg_constraint where conname = 'notifications_type_check') like '%sponsorship%'),
  ('members cannot read boosts that are not theirs', not exists (select 1 from pg_policies where tablename = 'sponsored_posts' and policyname = 'sponsored_posts_read' and qual not like '%is_admin()%'))
) as v(item, ok);
